function sigmoid(z){return 1/(1+Math.exp(-Math.max(-30,Math.min(30,z))))}function score(x){return w[0]*x[0]+w[1]*x[1]+b}function pred(x){let alg=$('algorithm').value;if(alg==='knn'){let k=Math.min(+$('knnK')?.value||5,data.length),votes=Array(Math.max(classes,1)).fill(0);data.map(d=>({y:d.y,dist:d.x.reduce((s,v,i)=>s+(v-(x[i]||0))**2,0)})).sort((a,b)=>a.dist-b.dist).slice(0,k).forEach(o=>votes[o.y]++);return votes.indexOf(Math.max(...votes))}if(alg==='linear')return score(x);return sigmoid(score(x))>=.5?1:0}function lossOne(d){let z=score(d.x);if($('algorithm').value==='linear')return .5*(z-d.y)**2;let p=sigmoid(z);return -(d.y*Math.log(p+1e-9)+(1-d.y)*Math.log(1-p+1e-9))}
function trainOne(){if($('algorithm').value==='knn'){let l=data.reduce((s,d)=>s+(pred(d.x)===d.y?0:1),0)/data.length;losses.push(l);history.push([0,0,0,l]);trained=true;return}if($('algorithm').value==='kmeans'){trainKmeans();return}let lr=Math.max(.0001,Math.min(2,+$('lr').value||.08)),batch=$('batch').value==='Mini-batch'?Math.min(16,data.length):data.length;let gw=[0,0],gb=0,ls=0;for(let i=0;i<batch;i++){let d=data[Math.floor(Math.random()*data.length)],z=score(d.x),p=$('algorithm').value==='linear'?z:sigmoid(z),err=p-d.y;gw[0]+=err*d.x[0];gw[1]+=err*d.x[1];gb+=err;ls+=lossOne(d)}w[0]-=lr*gw[0]/batch;w[1]-=lr*gw[1]/batch;b-=lr*gb/batch;let l=data.reduce((s,d)=>s+lossOne(d),0)/data.length;losses.push(l);history.push([...w,b,l]);if(history.length>250)history.shift();trained=true}
function trainKmeans(){if(!centers.length)centers=[data[0].x.slice(),data[Math.floor(data.length/2)].x.slice()];let sums=[[0,0,0],[0,0,0]];data.forEach(d=>{let c=nearest(d.x);sums[c][0]+=d.x[0];sums[c][1]+=d.x[1];sums[c][2]++});sums.forEach((s,i)=>{if(s[2])centers[i]=[s[0]/s[2],s[1]/s[2]]});losses.push(data.reduce((s,d)=>s+dist2(d.x,centers[nearest(d.x)]),0)/data.length);history.push([...centers[0],centers[1][0],centers[1][1],losses.at(-1)]);trained=true}
