async function runTraining(){let total=Math.min(2000,Math.max(1,+$('epochs').value||120));$('train').disabled=true;$('status').textContent='Training in corso…';for(let i=0;i<total;i++){trainOne();if(i%Math.max(1,Math.floor(total/80))===0){$('progress').style.width=(100*i/total)+'%';$('status').textContent=`Epoca ${i+1} / ${total}`;renderAll();await new Promise(r=>setTimeout(r,12))}}$('progress').style.width='100%';$('status').innerHTML='<span class="pill">Training completato</span> · '+total+' epoche';$('train').disabled=false;updateStats();renderAll()}
