function drawHist(){const {ctx,W,H}=setupCanvas($('histChart')),plot={left:48,right:W-12,top:14,bottom:H-38};if(!losses.length){drawNumericAxes(ctx,{...plot,xMin:0,xMax:1,yMin:0,yMax:1,xLabel:'Loss',yLabel:'Numero di epoche'});return}const n=12,min=Math.min(...losses),max=Math.max(...losses),bins=Array(n).fill(0);losses.forEach(v=>bins[Math.min(n-1,Math.floor((v-min)/(max-min||1)*n))]++);const maxCount=Math.max(...bins),range=max-min||1,countStep=Math.max(1,Math.ceil(maxCount/4)),countTicks=Array.from({length:Math.floor(maxCount/countStep)+1},(_,i)=>i*countStep);if(countTicks.at(-1)!==maxCount)countTicks.push(maxCount);drawNumericAxes(ctx,{...plot,xMin:min,xMax:max===min?min+1:max,yMin:0,yMax:maxCount,yTicks:countTicks,xFormat:v=>formatTick(v,v>=10?1:3),yFormat:v=>String(Math.round(v)),xLabel:'Loss',yLabel:'Numero di epoche'});const bw=(plot.right-plot.left)/n;bins.forEach((v,i)=>{ctx.fillStyle='#2995ff';const h=(plot.bottom-plot.top)*v/maxCount;ctx.fillRect(plot.left+i*bw,plot.bottom-h,bw-2,h)});ctx.fillStyle='#9bb6d6';ctx.fillText('frequenza loss',plot.left+6,plot.top+11)}
function renderSamples(){let rows=data.slice(0,12);$('sampleRows').innerHTML=rows.map((d,i)=>`<tr><td>${i+1}</td><td>${d.x[0].toFixed(2)}</td><td>${d.x[1].toFixed(2)}</td><td>${d.y}</td><td>${trained?pred(d.x):'—'}</td></tr>`).join('')}
function predict(){let x=[+$('in1').value||0,+$('in2').value||0],z=score(x),p=sigmoid(z),cl=$('algorithm').value==='kmeans'&&centers.length?nearest(x):(p>=.5?1:0);$('liveX1').textContent=x[0].toFixed(2);$('liveX2').textContent=x[1].toFixed(2);$('liveZ').textContent=z.toFixed(4);$('liveY').textContent=p.toFixed(4);$('predClass').textContent=$('algorithm').value==='linear'?'ŷ '+z.toFixed(2):'Classe '+cl;$('predProb').textContent=$('algorithm').value==='linear'?'valore stimato':`p(classe 1) ${(p*100).toFixed(1)}%`;$('probBars').innerHTML=`<div class="small" style="margin:8px 0 4px">Classe 0 <b style="float:right">${(100*(1-p)).toFixed(1)}%</b></div><div class="predictionbar"><span style="width:${100*(1-p)}%;background:${colors[0]}"></span></div><div class="small" style="margin:8px 0 4px">Classe 1 <b style="float:right">${(100*p).toFixed(1)}%</b></div><div class="predictionbar"><span style="width:${100*p}%;background:${colors[1]}"></span></div>`;$('explain').textContent=`z = (${w[0].toFixed(2)} × ${x[0].toFixed(2)}) + (${w[1].toFixed(2)} × ${x[1].toFixed(2)}) + ${b.toFixed(2)} = ${z.toFixed(3)}. ${trained?'La previsione usa i parametri appresi.':'I parametri non sono ancora addestrati.'}`}
function renderAll(){drawLoss();drawAccuracy();drawData();drawHist();renderSamples();updateWeightsOnly();renderNetworkViews()}
function updateWeightsOnly(){if($('algorithm').value==='kmeans'){$('weights').innerHTML=`<tr><td>Centroide 1</td><td>${centers[0]?.map(v=>v.toFixed(3)).join(', ')||'—'}</td></tr><tr><td>Centroide 2</td><td>${centers[1]?.map(v=>v.toFixed(3)).join(', ')||'—'}</td></tr><tr><td>Inerzia</td><td>${losses.at(-1)?.toFixed(4)||'—'}</td></tr>`}else $('weights').innerHTML=`<tr><td>w₁</td><td>${w[0].toFixed(4)}</td></tr><tr><td>w₂</td><td>${w[1].toFixed(4)}</td></tr><tr><td>b</td><td>${b.toFixed(4)}</td></tr>`}

function currentInput(){let arr=[];for(let i=0;i<(data[0]?.x.length||2);i++){let el=$('xInput'+i);arr.push(el?Number(el.value)||0:(i===0?(+$('in1').value||0):(i===1?(+$('in2').value||0):0)));}return arr}
function buildInputControls(){let n=data[0]?.x.length||2,box=$('inputControls');box.innerHTML='';for(let i=0;i<n;i++){let lab=document.createElement('label');lab.textContent=`Input x${i+1}${i<2?'':' · feature aggiuntiva'}`;let inp=document.createElement('input');inp.type='number';inp.step='0.1';inp.id='xInput'+i;inp.value=i===0?'0.8':i===1?'0.5':'0';inp.addEventListener('input',()=>{if(i===0)$('in1').value=inp.value;if(i===1)$('in2').value=inp.value;predict()});box.append(lab,inp)}for(let i=0;i<2;i++){let id='in'+(i+1),compat=document.getElementById(id);if(!compat){compat=document.createElement('input');compat.type='hidden';compat.id=id;box.append(compat)}compat.value=$('xInput'+i)?.value||'0'}}
$('knnK')?.addEventListener('change',()=>{if(trained)renderAll()});$('featureCount').addEventListener('change',generate);
// Method reference panel: formulas and hyperparameters are specific to the selected family.
const METHOD_INFO={
 logistic:{status:'Implementato per classificazione binaria; per più classi usa Softmax.',model:'p(y=1|x)=σ((w₁−w₀)ᵀx+b₁−b₀)',cost:'J = −(1/m)Σᵢ[yᵢlog(pᵢ)+(1−yᵢ)log(1−pᵢ)] + regolarizzazione',update:'θ ← θ − α∇J<br>θ = (w₁−w₀, b₁−b₀)',explain:'Stima la probabilità di una delle due classi con la funzione sigmoide. Per classificare più di due classi seleziona Softmax. Metriche: accuracy, precision, recall, F1 e matrice di confusione.'},
 softmax:{status:'Implementato nel motore come classificatore lineare multiclasse.',model:'p(y=k|x)= exp(wₖᵀx+bₖ) / Σⱼ exp(wⱼᵀx+bⱼ)',cost:'J = −(1/m)ΣᵢΣₖ yᵢₖ log(pᵢₖ) + (λ/2)‖W‖₂²',update:'W ← W − α[(1/m)Σᵢ(pᵢ−yᵢ)xᵢᵀ + λW]<br>b ← b − α(1/m)Σᵢ(pᵢ−yᵢ)',explain:'Un vettore di probabilità per ogni classe. Metriche: accuracy, macro/micro precision, recall, F1 e confusion matrix.'},
 perceptron:{status:'Implementato nel motore per classificazione binaria e multiclasse.',model:'ŷ = argmaxₖ(wₖᵀx+bₖ)',cost:'Aggiorna solo se ŷᵢ ≠ yᵢ',update:'wᵧ ← wᵧ + αx ; wŷ ← wŷ − αx<br>bᵧ ← bᵧ + α ; bŷ ← bŷ − α',explain:'Aggiorna i parametri quando un esempio è classificato male. Metriche: accuracy, precision, recall, F1.'},
 linear:{status:'Regressione lineare con feature originali o trasformate.',model:'ŷ = wᵀφ(x)+b',cost:'J = MSE/2 = (1/2m)Σᵢ(ŷᵢ−yᵢ)²',update:'w ← w − α(1/m)Σᵢeᵢφ(xᵢ)<br>b ← b − α(1/m)Σᵢeᵢ',explain:'Il grado automatico usa una base lineare, quadratica o polinomiale in base al dataset; puoi impostarlo manualmente. Metriche: MSE, RMSE, MAE e R².'},
 ridge:{status:'Ridge Regression implementata con feature originali o trasformate.',model:'ŷ = wᵀφ(x)+b',cost:'J = MSE/2 + λ‖w‖₂²/2',update:'w ← w − α[(1/m)Σᵢeᵢφ(xᵢ)+λw]<br>b ← b − α(1/m)Σᵢeᵢ',explain:'Regolarizzazione L2 sulla base selezionata: riduce i coefficienti senza azzerarli in generale. Puoi scegliere il grado delle feature.'},
 lasso:{status:'Lasso implementato con aggiornamento prossimale e feature trasformate.',model:'ŷ = wᵀφ(x)+b',cost:'J = MSE/2 + λ‖w‖₁',update:'u ← w − α∇(MSE/2)<br>w ← sign(u)·max(0,|u|−αλ)<br>b ← b − α∂(MSE/2)/∂b',explain:'Regolarizzazione L1 sulla base selezionata: può azzerare coefficienti e selezionare termini polinomiali. Puoi scegliere il grado delle feature.'},
 elastic:{status:'Elastic Net implementato con penalità L1 e L2.',model:'ŷ = wᵀφ(x)+b',cost:'J = MSE/2 + λ[ρ‖w‖₁ + (1−ρ)‖w‖₂²/2]',update:'w ← w − α[∇(MSE/2)+λ(1−ρ)w]<br>w ← proxₐλρ(w) ; b ← b − α∂(MSE/2)/∂b',explain:'Combina selezione delle feature (L1) e shrinkage (L2) sulla base scelta. Il grado automatico si adatta ai dataset sintetici; puoi modificarlo.'},
 knn:{status:'Implementato nel motore base; classificazione multiclasse e distanza sulle feature supportate.',model:'ŷ(x)= moda{yᵢ : xᵢ ∈ Nₖ(x)}',cost:'Nessuna funzione di costo ottimizzata: KNN è un metodo instance-based.',update:'Nessun aggiornamento dei pesi. Si memorizzano gli esempi; la previsione usa i k vicini.',explain:'Metriche: accuracy, precision, recall, F1, confusion matrix. Parametri: k, metrica e pesatura dei vicini.'},
 svmrbf:{status:'SVM con kernel RBF implementata tramite aggiornamento duale semplificato.',model:'K(x,z)=exp(−γ||x−z||²)',cost:'Hinge loss sul punteggio kernel<br>Lᵢ=max(0,1−yᵢf(xᵢ))',update:'αᵢ ← clip((1−yᵢ(otherᵢ+b))/Kᵢᵢ, 0, C)<br>b ← media(yᵢ−f(xᵢ)) sui support vector liberi',explain:'Kernel RBF produce frontiere non lineari. Parametri: C, γ, tolleranza, criterio multiclasse. Metriche di classificazione.'},
 svmpoly:{status:'SVM con kernel polinomiale implementata tramite aggiornamento duale semplificato.',model:'K(x,z)=(γxᵀz+r)ᵈ',cost:'Hinge loss sul punteggio kernel<br>Lᵢ=max(0,1−yᵢf(xᵢ))',update:'αᵢ ← clip((1−yᵢ(otherᵢ+b))/Kᵢᵢ, 0, C)<br>b ← media(yᵢ−f(xᵢ)) sui support vector liberi',explain:'Kernel polinomiale. Parametri: C, grado d, γ, coef0. Metriche di classificazione.'},
 tree:{status:'Decision Tree implementato con ricerca di split e criteri Gini/entropia.',model:'Nodo: split feature j e soglia t; foglia: classe maggioritaria',cost:'Gini = 1−Σₖpₖ²<br>oppure Entropy = −Σₖpₖ log₂pₖ',update:'Sceglie lo split con impurità pesata minima; ricorsione fino ai limiti impostati.',explain:'Parametri: profondità massima, min campioni split/foglia, criterio. Metriche: classificazione.'},
 forest:{status:'Random Forest implementata con bootstrap e selezione casuale delle feature.',model:'ŷ = moda{T₁(x),…,Tₙ(x)}',cost:'Impurità Gini/Entropy aggregata sugli split degli alberi',update:'Addestra alberi su campioni bootstrap e sottoinsiemi casuali di feature; aggrega per voto.',explain:'Parametri: numero alberi, profondità, max feature, bootstrap, min samples leaf. Metriche: classificazione e OOB se disponibile.'},
 boost:{status:'Gradient Boosting implementato per regressione e classificazione.',model:'Fₘ(x)=Fₘ₋₁(x)+ηhₘ(x)',cost:'L(y,F(x)) (es. errore quadratico o log-loss)',update:'Addestra hₘ sui residui/gradienti negativi correnti e aggiunge ηhₘ alla previsione.',explain:'Parametri: numero stimatori, learning rate, profondità/alberi, subsampling. Metriche: loss, accuracy, F1.'},
 naive:{status:'Naive Bayes implementato con varianti gaussiana, multinomiale e Bernoulli.',model:'P(y|x) ∝ P(y) ΠⱼP(xⱼ|y)',cost:'Negative log-likelihood dei parametri stimati dai dati',update:'Stima prior e distribuzioni condizionate dai campioni; non usa gradient descent standard.',explain:'Parametri: smoothing α, modello gaussiano/multinomiale/bernoulli. Metriche: classificazione.'},
 mlp:{status:'Rete neurale implementata con backpropagation e ottimizzatore Adam predefinito.',model:'a⁽ˡ⁾=φ(W⁽ˡ⁾a⁽ˡ⁻¹⁾+b⁽ˡ⁾)',cost:'Cross-entropy per classificazione; MSE/2 per regressione',update:'mₜ=β₁mₜ₋₁+(1−β₁)gₜ<br>vₜ=β₂vₜ₋₁+(1−β₂)gₜ²<br>W⁽ˡ⁾, b⁽ˡ⁾ ← Adam(W⁽ˡ⁾, b⁽ˡ⁾, gₜ)',explain:'La backpropagation calcola i gradienti di pesi e bias; Adam è l’ottimizzatore predefinito. Metriche: loss, accuracy o MSE e confusion matrix.'},
 sgd:{status:'SGD implementato come ottimizzatore della rete neurale.',model:'gₜ=∇θJᵢ(θₜ)',cost:'Jᵢ: loss del campione o mini-batch selezionato',update:'θₜ₊₁=θₜ−αgₜ',explain:'Parametri: learning rate, batch size, shuffle. Ottimizza il modello neurale selezionato.'},
 momentum:{status:'Momentum implementato come ottimizzatore della rete neurale.',model:'gₜ=∇θJ(θₜ)',cost:'J(θ): loss del batch corrente',update:'vₜ=μvₜ₋₁+gₜ<br>θₜ₊₁=θₜ−αvₜ',explain:'Parametri: learning rate α, momentum μ, batch size.'},
 nesterov:{status:'Nesterov implementato con gradiente nella posizione anticipata.',model:'gₜ=∇θJ(θₜ+vₜ₋₁)',cost:'J(θ): loss del batch corrente',update:'vₜ=μvₜ₋₁−αgₜ<br>θₜ₊₁=θₜ+vₜ',explain:'Valuta il gradiente al look-ahead θ+v e aggiorna la velocità. Parametri: α, μ.'},
 adagrad:{status:'AdaGrad implementato come ottimizzatore della rete neurale.',model:'gₜ=∇θJ(θₜ)',cost:'J(θ): loss del batch corrente',update:'rₜ=rₜ₋₁+gₜ⊙gₜ<br>θₜ₊₁=θₜ−αgₜ/(√rₜ+ε)',explain:'Learning rate adattivo per parametro. Parametri: α, epsilon.'},
 rmsprop:{status:'RMSProp implementato come ottimizzatore della rete neurale.',model:'gₜ=∇θJ(θₜ)',cost:'J(θ): loss del batch corrente',update:'rₜ=ρrₜ₋₁+(1−ρ)gₜ²<br>θₜ₊₁=θₜ−αgₜ/(√rₜ+ε)',explain:'Parametri: α, decay ρ, epsilon.'},
 adam:{status:'Adam implementato come ottimizzatore della rete neurale.',model:'gₜ=∇θJ(θₜ)',cost:'J(θ): loss del batch corrente',update:'mₜ=β₁mₜ₋₁+(1−β₁)gₜ<br>vₜ=β₂vₜ₋₁+(1−β₂)gₜ²<br>θₜ₊₁=θₜ−αm̂ₜ/(√v̂ₜ+ε)',explain:'Parametri: α, β₁, β₂, epsilon. m̂ e v̂ sono corretti per il bias iniziale.'},
 adamw:{status:'AdamW implementato con weight decay disaccoppiato.',model:'gₜ=∇θJ(θₜ)',cost:'J(θ): loss del batch corrente; il weight decay è separato',update:'Adam: θ′=θ−αm̂ₜ/(√v̂ₜ+ε)<br>θₜ₊₁=θ′−αλθₜ',explain:'Weight decay disaccoppiato. Parametri: α, β₁, β₂, epsilon, λ.'},
 kmeans:{status:'Implementato nel motore base come clustering.',model:'assegna xᵢ al centro μₖ più vicino',cost:'Inertia = Σᵢ minₖ ||xᵢ−μₖ||²',update:'Assegnazione: cᵢ=argminₖ||xᵢ−μₖ||²<br>Centro: μₖ=media{xᵢ:cᵢ=k}',explain:'Parametri: numero cluster k, inizializzazione, iterazioni. Metriche: inertia e silhouette (se calcolata).'},
 dbscan:{status:'DBSCAN implementato con espansione dei cluster per densità.',model:'Core point se |Nε(x)| ≥ minPts; cluster tramite densità',cost:'Non minimizza una funzione di costo globale standard',update:'Conta i vicini entro ε; espande i punti raggiungibili e identifica il rumore.',explain:'Parametri: epsilon, minPts, metrica. Metriche: silhouette sui punti assegnati, numero cluster e rumore.'},
 gmm:{status:'Gaussian Mixture Model implementato con algoritmo EM.',model:'p(x)=Σₖπₖ N(x|μₖ,Σₖ)',cost:'Negative log-likelihood: −Σᵢ log ΣₖπₖN(xᵢ|μₖ,Σₖ)',update:'EM: E-step calcola responsabilità; M-step aggiorna πₖ, μₖ, Σₖ.',explain:'Parametri: componenti, covarianza, regolarizzazione, iterazioni. Metriche: log-likelihood, AIC/BIC.'}
};
