 perceptron:[['x, xᵢ','Vettore delle feature del campione.'],['yᵢ','Indice della classe vera.'],['wₖ, bₖ','Pesi e bias del punteggio della classe k.'],['zₖ','Punteggio lineare wₖᵀx+bₖ.'],['ŷ','Classe con il punteggio più alto.'],['α','Learning rate usato nell’aggiornamento della classe vera e di quella predetta.'],['i, k','Indici di campione e classe.']],
