// === Integrated learning engine: the selected method now controls fit, predict and metrics. ===
const ENGINE_STATIC = new Set(['knn','tree','forest','naive','dbscan']);
const ENGINE_CLUSTER = new Set(['kmeans','dbscan','gmm']);
const ENGINE_REGRESSION = new Set(['linear','ridge','lasso','elastic']);
let engine = { id:null, model:null, previousModel:null, train:[], test:[], metrics:{}, iteration:0, fitted:false, gradNorm:0, lastLoss:NaN };
let engineSync = false;
function methodId(){ return $('methodSelect')?.value || $('algorithm')?.value || 'logistic'; }
function isClustering(){ return ENGINE_CLUSTER.has(methodId()); }
function isRegressionTask(id=methodId()){return ENGINE_REGRESSION.has(id)||(id==='boost'&&engine.model?.regression)||((id==='mlp'||['sgd','momentum','nesterov','adagrad','rmsprop','adam','adamw'].includes(id))&&classes===1&&$('dataset').value!=='oneclass');}
function methodCompatibilityIssue(id=methodId()){if(id==='logistic'&&classes!==2)return 'La regressione logistica è binaria; per più di due classi usa Softmax.';const regressionDataset=$('dataset').value.startsWith('regression');if(classes<2&&!regressionDataset&&!ENGINE_CLUSTER.has(id)&&!ENGINE_REGRESSION.has(id))return 'Un solo target non definisce un problema di classificazione supervisionata. Passa a Clustering per esplorare questi dati.';return '';}
function regressionBasisDegree(){const choice=param('featureDegree','auto');if(choice!=='auto')return Math.max(1,Math.min(5,Number(choice)||1));if(customRegressionData)return 1;const dataset=$('dataset').value;return dataset==='regression_quadratic'||dataset==='regression_interaction'?2:dataset==='regression_sine'?5:1;}
function regressionFeatureNames(dimensions,degree){const names=[];for(let i=0;i<dimensions;i++){names.push(`x${i+1}`);for(let power=2;power<=degree;power++)names.push(`x${i+1}^${power}`);}if(degree>=2)for(let i=0;i<dimensions;i++)for(let j=i+1;j<dimensions;j++)names.push(`x${i+1}·x${j+1}`);return names;}
function rawRegressionFeatures(x,degree){const values=[];for(let i=0;i<x.length;i++){values.push(x[i]||0);for(let power=2;power<=degree;power++)values.push((x[i]||0)**power);}if(degree>=2)for(let i=0;i<x.length;i++)for(let j=i+1;j<x.length;j++)values.push((x[i]||0)*(x[j]||0));return values;}
function makeRegressionModel(rows){const degree=regressionBasisDegree(),features=rows.map(row=>rawRegressionFeatures(row.x,degree)),means=features[0].map((_,i)=>features.reduce((sum,row)=>sum+row[i],0)/(rows.length||1)),scales=features[0].map((_,i)=>{const variance=features.reduce((sum,row)=>sum+(row[i]-means[i])**2,0)/(rows.length||1);return Math.sqrt(variance)||1});return {kind:'linear',degree,means,scales,w:Array(means.length).fill(0),b:0};}
