function regressionPlotInput(x,dimensions){const values=Array(dimensions).fill(0);values[0]=x;for(let i=1;i<dimensions;i++)values[i]=engine.train.length?engine.train.reduce((sum,row)=>sum+(row.x[i]||0),0)/engine.train.length:0;return values;}
function param(key, fallback){ const el=$('methodParam_'+key); if(!el) return fallback; if(el.tagName==='SELECT') return el.value; const v=Number(el.value); return Number.isFinite(v)?v:fallback; }
function pNum(key, fallback, min=-Infinity, max=Infinity){ return Math.max(min,Math.min(max,param(key,fallback))); }
function pBool(key, fallback=false){ const v=param(key,String(fallback)); return v==='true'||v===true; }
function shuffleCopy(a){const r=a.slice();for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}return r;}
function vecDist(a,b,metric='euclidean'){let s=0;if(metric==='manhattan'){for(let i=0;i<a.length;i++)s+=Math.abs((a[i]||0)-(b[i]||0));return s;}for(let i=0;i<a.length;i++)s+=((a[i]||0)-(b[i]||0))**2;return Math.sqrt(s);}
function softmax(z){const m=Math.max(...z),e=z.map(v=>Math.exp(Math.max(-40,Math.min(40,v-m)))),s=e.reduce((a,b)=>a+b,0)||1;return e.map(v=>v/s)}
function classCounts(rows,k){const c=Array(k).fill(0);rows.forEach(d=>{if(d.y>=0&&d.y<k)c[d.y]++});return c;}
function updateTrainingControlAvailability(){const disabled=Boolean(methodCompatibilityIssue());$('train').disabled=disabled;$('step').disabled=disabled;}
function engineReset(){trainingRunning=false;engine={id:methodId(),model:null,previousModel:null,train:[],test:[],metrics:{},iteration:0,fitted:false,gradNorm:0,lastLoss:NaN};trained=false;history=[];losses=[];trainAccuracyHistory=[];testAccuracyHistory=[];centers=[];w=[0,0];b=0;updateTrainingControlAvailability();$('train').textContent='▶ Avvia / Continua';$('trainingPause')&&($('trainingPause').disabled=true);}
function engineInit(){const id=methodId(),rows=shuffleCopy(data),cut=Math.max(1,Math.min(rows.length-1,Math.floor(rows.length*(+$('split').value||.8))));engine={id,model:null,previousModel:null,train:rows.slice(0,cut),test:rows.slice(cut),metrics:{},iteration:0,fitted:false,gradNorm:0,lastLoss:NaN};if(rows.length<3){engine.train=rows;engine.test=rows;}
 const d=data[0]?.x.length||2,k=Math.max(1,classes),outputMode=$('nnOutput')?.value||'auto',mlpOutputs=classes===1?1:(outputMode==='binary'&&k===2?1:k);
 if(ENGINE_REGRESSION.has(id))engine.model=makeRegressionModel(engine.train);
 else if(id==='logistic'||id==='softmax'||id==='perceptron')engine.model={kind:id,w:Array.from({length:k},()=>Array(d).fill(0)),b:Array(k).fill(0)};
 else if(id==='knn')engine.model={kind:'knn',rows:engine.train};
 else if(id==='svmrbf'||id==='svmpoly'){const n=engine.train.length;engine.model={kind:'svm',kernel:id==='svmrbf'?'rbf':'poly',alpha:Array.from({length:k},()=>Array(n).fill(0)),bias:Array(k).fill(0),labels:Array.from({length:k},(_,c)=>engine.train.map(r=>r.y===c?1:-1)),K:Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>svmKernel(engine.train[i].x,engine.train[j].x,id))),classes:k};}
 else if(id==='tree')engine.model={kind:'tree',root:null};
 else if(id==='forest')engine.model={kind:'forest',trees:[]};
 else if(id==='boost')engine.model={kind:'boost',trees:Array.from({length:k},()=>[]),base:Array(k).fill(0),regression:classes===1&&$('dataset').value!=='oneclass'};
 else if(id==='naive')engine.model={kind:'naive',stats:[]};
 else if(id==='mlp'||['sgd','momentum','nesterov','adagrad','rmsprop','adam','adamw'].includes(id))engine.model=makeMLP(d,ENGINE_REGRESSION.has(id)?1:mlpOutputs,id);
 else if(id==='kmeans'){const k=Math.min(Math.round(pNum('clusters',3,1,20)),engine.train.length);const init=param('init','kmeans++')==='random'?shuffleCopy(engine.train).slice(0,k).map(r=>r.x.slice()):initCentroids(engine.train,k);engine.model={kind:'kmeans',centroids:init,labels:[]};}
 else if(id==='dbscan')engine.model={kind:'dbscan',labels:[]};
 else if(id==='gmm')engine.model=makeGMM(engine.train,pNum('components',3,1,12));
 else engine.model={kind:'linear',w:Array(d).fill(0),b:0};
 if(engine.model?.centroids){centers=engine.model.centroids.map(v=>v.slice());}
}
