function engineLoss(){const id=engine.id,m=engine.model,rows=engine.train;if(!rows.length)return 0;if(ENGINE_REGRESSION.has(id)){const mse=rows.reduce((s,r)=>s+(enginePredict(r.x)-r.y)**2,0)/rows.length;const lambda=id==='linear'?0:pNum('lambda',.1,0,100),ratio=id==='lasso'?1:id==='linear'||id==='ridge'?0:pNum('l1Ratio',.5,0,1);return mse/2+lambda*(ratio*m.w.reduce((s,v)=>s+Math.abs(v),0)+(1-ratio)*.5*m.w.reduce((s,v)=>s+v*v,0));}if(id==='logistic'||id==='softmax'){return rows.reduce((sum,r)=>{const pr=softmax(m.w.map((v,c)=>v.reduce((s,t,i)=>s+t*r.x[i],m.b[c])));return sum-Math.log(Math.max(1e-12,pr[r.y]));},0)/rows.length+pNum('lambda',0,0,100)*m.w.reduce((s,v)=>s+v.reduce((a,b)=>a+b*b,0),0)/2;}if(id==='kmeans')return rows.reduce((s,r)=>s+Math.min(...m.centroids.map(c=>vecDist(r.x,c)**2)),0)/rows.length;if(id==='dbscan')return m.labels.filter(v=>v===-1).length/rows.length;if(id==='gmm')return -rows.reduce((s,r)=>s+Math.log(Math.max(1e-300,m.means.reduce((v,mu,c)=>v+m.mix[c]*gaussianPdf(r.x,mu,m.covs[c]),0))),0);if(id==='svmrbf'||id==='svmpoly'){let s=0;for(let c=0;c<m.classes;c++)for(let i=0;i<rows.length;i++){const f=m.bias[c]+m.alpha[c].reduce((a,v,j)=>a+v*m.labels[c][j]*m.K[j][i],0);s+=Math.max(0,1-m.labels[c][i]*f);}return s/rows.length;}if(id==='mlp'||['sgd','momentum','nesterov','adagrad','rmsprop','adam','adamw'].includes(id))return mlpGrad(m,rows).loss;if(id==='boost'&&m.regression)return rows.reduce((s,r)=>s+(enginePredict(r.x)-r.y)**2,0)/rows.length;if(isClustering())return rows.reduce((s,r)=>s+(enginePredict(r.x)>=0?0:1),0)/rows.length;let wrong=rows.filter(r=>enginePredict(r.x)!==r.y).length;return wrong/rows.length;}
