 if(!chartViewport)return;
 const rect=chartViewport.getBoundingClientRect(),x=clientX??rect.left+rect.width/2,y=clientY??rect.top+rect.height/2;
 const next=Math.max(.65,Math.min(12,chartView.zoom*factor)),ratio=next/chartView.zoom;
